-- Whether the invoice repeats every period: a sent recurring invoice can generate the next period's draft.
ALTER TABLE invoice ADD COLUMN recurring BOOLEAN NOT NULL DEFAULT FALSE;
-- The id of the recurring invoice this draft was generated from as its next period; null when it was not.
ALTER TABLE invoice ADD COLUMN recurring_from BIGINT;
-- The last day a recurring invoice bills for: a generated period stops on it, and none starting after it is generated; null for no end.
ALTER TABLE invoice ADD COLUMN recur_until DATE;
-- The most the client may owe, in the client's currency: an invoice that would take its balance over
-- it is not sent. NULL for no limit.
ALTER TABLE client ADD COLUMN credit_limit DECIMAL(19, 2);
